#include <algorithm>
#include <cmath>
#include <iomanip>
#include <iostream>

struct Call {
    double operator()(double S, double K) const { return std::max(S - K, 0.0); }
};

double norm_cdf(double x) {
    return 0.5 * std::erfc(-x / std::sqrt(2.0));
}

// Black-Scholes value of a European call: spot S, strike K, rate r, vol sigma, T years
double bs_call(double S, double K, double r, double sigma, double T) {
    if (T <= 0.0 || sigma <= 0.0) {
        return std::max(S - K * std::exp(-r * T), 0.0);  // no uncertainty left
    }
    const double sd = sigma * std::sqrt(T);
    const double d1 = (std::log(S / K) + (r + 0.5 * sigma * sigma) * T) / sd;
    const double d2 = d1 - sd;
    return S * norm_cdf(d1) - K * std::exp(-r * T) * norm_cdf(d2);
}

double bs_put(double S, double K, double r, double sigma, double T) {
    if (T <= 0.0 || sigma <= 0.0) {
        return std::max(K * std::exp(-r * T) - S, 0.0);
    }
    const double sd = sigma * std::sqrt(T);
    const double d1 = (std::log(S / K) + (r + 0.5 * sigma * sigma) * T) / sd;
    const double d2 = d1 - sd;
    return K * std::exp(-r * T) * norm_cdf(-d2) - S * norm_cdf(-d1);
}

int main() {
    const double S = 100.0, r = 0.05, sigma = 0.20, T = 1.0;
    const double strikes[] = {80.0, 90.0, 100.0, 110.0, 120.0};
    double worst_gap = 0.0;
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "    K      call       put  payoff now\n";
    for (double K : strikes) {
        const double c = bs_call(S, K, r, sigma, T);
        const double p = bs_put(S, K, r, sigma, T);
        const double gap = std::abs((c - p) - (S - K * std::exp(-r * T)));
        worst_gap = std::max(worst_gap, gap);
        std::cout << std::setw(5) << std::setprecision(0) << K << std::setprecision(4)
                  << std::setw(10) << c << std::setw(10) << p << std::setw(12) << Call{}(S, K) << '\n';
    }
    std::cout << "largest put-call parity gap " << std::scientific << std::setprecision(1) << worst_gap << '\n';

    std::cout << std::fixed << std::setprecision(4) << "K 100 call as expiry nears:";
    const double expiries[] = {1.0, 0.25, 1.0 / 52, 1.0 / 365, 0.0};
    for (double t : expiries) {
        std::cout << ' ' << bs_call(105.0, 100.0, r, sigma, t);
    }
    std::cout << '\n';
    return 0;
}

