#include <cmath>
#include <iomanip>
#include <iostream>

struct Digital {
    double operator()(double S, double K) const { return S > K ? 1.0 : 0.0; }
};

double norm_cdf(double x) {
    return 0.5 * std::erfc(-x / std::sqrt(2.0));
}

double bs_d2(double S, double K, double r, double sigma, double T) {
    return (std::log(S / K) + (r - 0.5 * sigma * sigma) * T) / (sigma * std::sqrt(T));
}

double bs_digital_call(double S, double K, double r, double sigma, double T) {
    return std::exp(-r * T) * norm_cdf(bs_d2(S, K, r, sigma, T));
}

double bs_digital_put(double S, double K, double r, double sigma, double T) {
    return std::exp(-r * T) * norm_cdf(-bs_d2(S, K, r, sigma, T));
}

int main() {
    double S = 0.0, r = 0.0, sigma = 0.0, T = 0.0;
    int n = 0;
    std::cin >> S >> r >> sigma >> T >> n;
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "    K   digital  dig put      sum  payoff now\n";
    for (int i = 0; i < n; ++i) {
        double K = 0.0;
        std::cin >> K;
        const double c = bs_digital_call(S, K, r, sigma, T);
        const double p = bs_digital_put(S, K, r, sigma, T);
        std::cout << std::setw(5) << std::setprecision(0) << K << std::setprecision(4) << std::setw(10) << c
                  << std::setw(9) << p << std::setw(9) << c + p << std::setw(12) << Digital{}(S, K) << '\n';
    }
