#include <cmath>
#include <iomanip>
#include <iostream>

double norm_cdf(double x) { return 0.5 * std::erfc(-x / std::sqrt(2.0)); }
double norm_pdf(double x) { return 0.3989422804014327 * std::exp(-0.5 * x * x); }

struct Market {
    double S0, K, r, sigma, T;  // spot, strike, rate, volatility, years to expiry
};

double bs_call(const Market& m) {
    const double sd = m.sigma * std::sqrt(m.T);
    const double d1 = (std::log(m.S0 / m.K) + (m.r + 0.5 * m.sigma * m.sigma) * m.T) / sd;
    return m.S0 * norm_cdf(d1) - m.K * std::exp(-m.r * m.T) * norm_cdf(d1 - sd);
}

struct Greeks {
    double delta, gamma, vega, theta;
};

Greeks bs_call_greeks(const Market& m) {
    const double sd = m.sigma * std::sqrt(m.T);
    const double d1 = (std::log(m.S0 / m.K) + (m.r + 0.5 * m.sigma * m.sigma) * m.T) / sd;
    const double d2 = d1 - sd;
    Greeks g;
    g.delta = norm_cdf(d1);
    g.gamma = norm_pdf(d1) / (m.S0 * sd);
    g.vega = m.S0 * norm_pdf(d1) * std::sqrt(m.T);
    g.theta = -m.S0 * norm_pdf(d1) * m.sigma / (2.0 * std::sqrt(m.T)) - m.r * m.K * std::exp(-m.r * m.T) * norm_cdf(d2);
    return g;
}

void show(const char* name, double closed, double bumped) {
    std::cout << std::setw(5) << name << std::fixed << std::setprecision(8) << std::setw(13) << closed
              << std::setw(13) << bumped << "  gap " << std::scientific << std::setprecision(1)
              << std::abs(closed - bumped) << '\n';
}

int main() {
    const Market m{100.0, 100.0, 0.05, 0.20, 1.0};
    const double S = m.S0, v = m.sigma, T = m.T;
    const double hS = 0.01, hv = 1e-5, hT = 1e-5;
    const Greeks g = bs_call_greeks(m);
    // reprice with spot, volatility, or time moved: a copy of m with those three fields changed
    auto C = [&](double s, double vol, double t) { return bs_call(Market{s, m.K, m.r, vol, t}); };

    std::cout << " name       closed   finite diff\n";
    show("delta", g.delta, (C(S + hS, v, T) - C(S - hS, v, T)) / (2 * hS));
    show("gamma", g.gamma, (C(S + hS, v, T) - 2 * C(S, v, T) + C(S - hS, v, T)) / (hS * hS));
    show("vega", g.vega, (C(S, v + hv, T) - C(S, v - hv, T)) / (2 * hv));
    show("theta", g.theta, -(C(S, v, T + hT) - C(S, v, T - hT)) / (2 * hT));
    std::cout << std::fixed << std::setprecision(4) << "vega per vol point " << g.vega / 100
              << ", theta per day " << g.theta / 365 << '\n';
    return 0;
}

