}

double bs_vega(const Market& m) {
    const double d1 = (std::log(m.S0 / m.K) + (m.r + 0.5 * m.sigma * m.sigma) * m.T) / (m.sigma * std::sqrt(m.T));
    return m.S0 * norm_pdf(d1) * std::sqrt(m.T);
}

struct ImpliedVol {
    double sigma;
    int newton, bisect;  // how many steps of each it took
};

// m.sigma is ignored: it is the unknown the solver searches for
std::optional<ImpliedVol> implied_vol_call(double price, Market m) {
    if (price <= std::max(m.S0 - m.K * std::exp(-m.r * m.T), 0.0) || price >= m.S0) {
        return std::nullopt;  // outside the no-arbitrage bounds: no volatility gives this price
    }
    double lo = 0.0, hi = 5.0;
    m.sigma = 0.2;
    ImpliedVol out{0.0, 0, 0};
    for (int i = 0; i < 100; ++i) {
        const double diff = bs_call(m) - price;
        if (std::abs(diff) < 1e-10) {
            out.sigma = m.sigma;
            return out;
        }
        if (diff > 0) {
            hi = m.sigma;  // too expensive: the answer is below sigma
        } else {
            lo = m.sigma;  // too cheap: the answer is above sigma
        }
        const double next = m.sigma - diff / bs_vega(m);
        if (next > lo && next < hi) {
            m.sigma = next;
            ++out.newton;
        } else {
            m.sigma = 0.5 * (lo + hi);  // Newton left the bracket: bisect instead
            ++out.bisect;
        }
    }
    return std::nullopt;  // no convergence in 100 steps: it needs a vol above 500%
}

int main() {
    struct Quote { double K, T, price; };
    const Quote quotes[] = {{100, 1.0, 10.45}, {150, 0.25, 1.62}, {200, 0.1, 0.73}, {80, 1.0, 22.00}, {100, 1.0, 100.50}};
    std::cout << std::fixed;
    for (const Quote& q : quotes) {
        std::cout << "K " << std::setprecision(0) << q.K << " T " << std::setprecision(2) << q.T
                  << " price " << q.price << " -> ";
        const std::optional<ImpliedVol> iv = implied_vol_call(q.price, Market{100.0, q.K, 0.05, 0.0, q.T});
        if (iv) {
            std::cout << "vol " << std::setprecision(6) << iv->sigma << " (newton " << iv->newton
                      << ", bisect " << iv->bisect << ")\n";
        } else {
            std::cout << "no solution\n";
        }
    }
    return 0;
}

