#include <optional>

double norm_cdf(double x) { return 0.5 * std::erfc(-x / std::sqrt(2.0)); }
double norm_pdf(double x) { return 0.3989422804014327 * std::exp(-0.5 * x * x); }

struct Market {
    double S0, K, r, sigma, T;  // spot, strike, rate, volatility, years to expiry
};

double bs_put(const Market& m) {
    const double sd = m.sigma * std::sqrt(m.T);
    const double d1 = (std::log(m.S0 / m.K) + (m.r + 0.5 * m.sigma * m.sigma) * m.T) / sd;
    return m.K * std::exp(-m.r * m.T) * norm_cdf(sd - d1) - m.S0 * norm_cdf(-d1);
}

double bs_vega(const Market& m) {
    const double d1 = (std::log(m.S0 / m.K) + (m.r + 0.5 * m.sigma * m.sigma) * m.T) / (m.sigma * std::sqrt(m.T));
    return m.S0 * norm_pdf(d1) * std::sqrt(m.T);
}

std::optional<double> implied_vol_put(double price, Market m) {
    const double pv_strike = m.K * std::exp(-m.r * m.T);
    if (price <= std::max(pv_strike - m.S0, 0.0) || price >= pv_strike) {
        return std::nullopt;
    }
    double lo = 0.0, hi = 5.0;
    m.sigma = 0.2;
    for (int i = 0; i < 100; ++i) {
        const double diff = bs_put(m) - price;
        if (std::abs(diff) < 1e-10) {
            return m.sigma;
        }
        if (diff > 0) {
            hi = m.sigma;
        } else {
            lo = m.sigma;
        }
        const double next = m.sigma - diff / bs_vega(m);
        m.sigma = (next > lo && next < hi) ? next : 0.5 * (lo + hi);
    }
    return std::nullopt;
}

int main() {
    int n = 0;
    std::cin >> n;
    std::cout << std::fixed;
    for (int i = 0; i < n; ++i) {
        Market m{};
        double price = 0.0;
        std::cin >> m.S0 >> m.K >> m.r >> m.T >> price;
        std::cout << "K " << std::setprecision(0) << m.K << " price " << std::setprecision(2) << price << ": ";
        const std::optional<double> vol = implied_vol_put(price, m);
        if (vol) {
            std::cout << "vol " << std::setprecision(4) << *vol << '\n';
        } else {
            std::cout << "no solution\n";
        }
    }
